trait Shape {                          // contract; traits cannot hold fields
    fn area(&self) -> f64;
    fn describe(&self) -> String { format!("area {:.2}", self.area()) }
}

struct Square { side: f64 }            // state lives in the implementation
impl Shape for Square {
    fn area(&self) -> f64 { self.side * self.side }
}

fn render(shapes: &[Box<dyn Shape>]) { for s in shapes { println!("{}", s.describe()); } }

