trait Summary { fn summarize(&self) -> String; }

fn notify<T: Summary>(item: &T) {          // static dispatch, monomorphised
    println!("{}", item.summarize());
}

fn notify_all(items: &[&impl Summary]) {   // same, with impl Trait sugar
    for i in items { notify(i); }
}
